input.sparql:
SELECT ?point ?cls ?tsid WHERE {
  ?point a brick:Electric_Power ; ref:hasTimeseriesId ?tsid .
  FILTER(str(?point) LIKE "%CHWPump02%")
}

SELECT ?point ?tsid WHERE {
  ?point a brick:Electric_Power .
  ?point ref:hasTimeseriesId ?tsid .
  FILTER (CONTAINS(str(?point), "CHWPump02"))
}

SELECT ?tsid WHERE {
  ?point a brick:Electric_Power_Sensor .
  FILTER (CONTAINS(str(?point), "CHWPump02"))
  ?point ref:hasTimeseriesId ?tsid .
}
